ALTER POLICY memberships_read ON public.room_members USING(user_id=auth.uid() OR public.in_room(room_id,auth.uid()));
CREATE FUNCTION public.room_member_count(_room uuid) RETURNS bigint LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT count(*) FROM public.room_members WHERE room_id=_room AND auth.uid() IS NOT NULL $$;
REVOKE ALL ON FUNCTION public.room_member_count(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.room_member_count(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.reserve_photo(_path text,_style text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE actor uuid:=auth.uid(); job uuid; quota integer; BEGIN IF actor IS NULL OR NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=actor) OR _path NOT LIKE actor::text||'/%' OR _style NOT IN('sakura','cinematic','manga') OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='profile-originals' AND name=_path AND owner_id=actor::text) THEN RAISE EXCEPTION 'Save your profile and upload your own photo first'; END IF; IF _style<>'sakura' AND NOT public.is_premium(actor) THEN RAISE EXCEPTION 'Additional styles require premium'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(actor::text,1)); quota:=CASE WHEN public.is_premium(actor) THEN 10 ELSE 2 END; IF (SELECT count(*) FROM public.photo_jobs WHERE user_id=actor AND status<>'failed' AND created_at>=(date_trunc('month',now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'))>=quota THEN RAISE EXCEPTION 'Monthly anime photo conversion allowance reached'; END IF; IF EXISTS(SELECT 1 FROM public.photo_jobs WHERE user_id=actor AND original_path=_path) THEN RAISE EXCEPTION 'This photo was already submitted; upload a new photo for a fresh attempt'; END IF; INSERT INTO public.photo_jobs(user_id,original_path,style) VALUES(actor,_path,_style) RETURNING id INTO job; RETURN job; END $$;
REVOKE ALL ON FUNCTION public.reserve_photo(text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.reserve_photo(text,text) TO authenticated;